<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">

    <title>Подтверждение email</title>

    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: #f4f6f8;
            font-family: Arial, Helvetica, sans-serif;
            color: #193f68;
        }

        table {
            border-spacing: 0;
            border-collapse: collapse;
        }

        @media only screen and (max-width: 600px) {
            .container {
                width: 100% !important;
            }

            .content {
                padding: 35px 20px !important;
            }

            .code {
                font-size: 34px !important;
                letter-spacing: 8px !important;
            }
        }
    </style>
</head>

<body>

<table width="100%" cellpadding="0" cellspacing="0" border="0"
       style="background-color:#f4f6f8; padding:40px 10px;">

    <tr>
        <td align="center">

            <!-- Main container -->
            <table class="container"
                   width="600"
                   cellpadding="0"
                   cellspacing="0"
                   border="0"
                   style="width:600px; max-width:600px; background-color:#ffffff;">

                <!-- Top blue line -->
                <tr>
                    <td style="height:6px; background-color:#193f68; font-size:0; line-height:0;">
                        &nbsp;
                    </td>
                </tr>

                <!-- Logo -->
                <tr>
                    <td align="center"
                        style="padding:35px 20px 30px 20px;">

                        <!--
                            ЛОГОТИП

                            Вставьте сюда свой SVG:

                            <svg ...>
                                ...
                            </svg>

                            Или:

                            <img src="..." width="180" alt="Logo">
                        -->



