                    </td>
                </tr>

                <!-- Separator -->
                <tr>
                    <td style="
                        height:1px;
                        background-color:#edf0f3;
                        font-size:0;
                        line-height:0;
                    ">
                        &nbsp;
                    </td>
                </tr>

                <!-- Content -->
                <tr>
                    <td class="content"
                        align="center"
                        style="padding:30px 50px 40px 50px;">

                        <!-- Text -->
                        <div style="
                            font-size:16px;
                            line-height:26px;
                            color:#5f6b78;
                        ">
                            Здравствуйте!
                            <br><br>
                            Для подтверждения вашего email-адреса
                            <br>
                            используйте код ниже.
                        </div>

                        <!-- Code -->
                        <table width="100%"
                               cellpadding="0"
                               cellspacing="0"
                               border="0"
                               style="margin:35px 0;">

                            <tr>
                                <td align="center"
                                    style="
                                        border:2px solid #f6b22a;
                                        border-radius:10px;
                                        background-color:#fffdf8;
                                        padding:25px 10px;
                                    ">

                                    <div class="code"
                                         style="
                                            font-size:42px;
                                            line-height:50px;
                                            font-weight:700;
                                            letter-spacing:12px;
                                            color:#193f68;
                                            padding-left:12px;
                                         ">
                                        {{ $code }}
                                    </div>

                                </td>
                            </tr>

                        </table>

                        <!-- Expiration -->
                        <div style="
                            font-size:14px;
                            line-height:22px;
                            color:#7a8694;
                        ">
                            Код действителен в течение
                            <strong style="color:#193f68;">
                                10 минут
                            </strong>
                        </div>

                        <div style="
                            margin-top:12px;
                            font-size:14px;
                            line-height:22px;
                            color:#9aa3ad;
                        ">
                            Если вы не запрашивали подтверждение,
                            просто проигнорируйте это письмо.
                        </div>

                    </td>
                </tr>

                <!-- Footer -->
                <tr>
                    <td style="
                        background-color:#193f68;
                        border-top:4px solid #f6b22a;
                        padding:30px 30px 25px 30px;
                    ">

                        <table width="100%"
                               cellpadding="0"
                               cellspacing="0"
                               border="0">

                            <tr>
                                <td align="center">

                                    <!-- Footer separator -->


                                    <div style="
                                        font-size:12px;
                                        line-height:18px;
                                        color:#9fb1c5;
                                    ">
                                        © {{ date('Y') }}
                                        GeoCar
                                    </div>

                                </td>
                            </tr>

                        </table>

                    </td>
                </tr>

            </table>

        </td>
    </tr>

</table>

</body>
</html>
